-- YG-1044–1047 erişim incelemesi; YG-585, 587, 1068 etik bildirim; YG-1673–1682 iç denetim.
CREATE TABLE erisim_inceleme (kimlik uuid PRIMARY KEY DEFAULT gen_random_uuid(), donem text NOT NULL, kapsam text NOT NULL, rol_ref text NOT NULL REFERENCES rol (kimlik), son_zaman timestamptz NOT NULL, eskalasyon_zamani timestamptz, durum text NOT NULL DEFAULT 'Açık' CHECK (durum IN ('Açık', 'Tamamlandı')), olusturma_zamani timestamptz NOT NULL DEFAULT now());
CREATE TABLE erisim_inceleme_kalemi (kimlik uuid PRIMARY KEY DEFAULT gen_random_uuid(), inceleme_ref uuid NOT NULL REFERENCES erisim_inceleme (kimlik), atama_ref uuid NOT NULL, kullanici_ref text NOT NULL REFERENCES kullanici_hesabi (kimlik), rol_ref text NOT NULL REFERENCES rol (kimlik), karar text CHECK (karar IN ('Koru', 'Daralt', 'Süre Uzat', 'Askıya Al', 'Kapat')), gerekce text, karar_ref text REFERENCES kullanici_hesabi (kimlik), karar_zamani timestamptz, uygulandi boolean NOT NULL DEFAULT false);
CREATE INDEX erisim_kalem_inceleme ON erisim_inceleme_kalemi (inceleme_ref);
CREATE TABLE etik_bildirim (kimlik uuid PRIMARY KEY DEFAULT gen_random_uuid(), bildirim_no text NOT NULL UNIQUE, kategori text NOT NULL, aciklama text NOT NULL, dosya_ref uuid REFERENCES dosya (kimlik), giren_ref text NOT NULL REFERENCES kullanici_hesabi (kimlik), makam_rol_ref text NOT NULL REFERENCES rol (kimlik), durum text NOT NULL DEFAULT 'Açık' CHECK (durum IN ('Açık', 'Kapalı')), sonuc text, yat_sahibi_karari text, karar_ref text REFERENCES kullanici_hesabi (kimlik), karar_zamani timestamptz, olusturma_zamani timestamptz NOT NULL DEFAULT now());
CREATE TABLE ic_denetim (kimlik uuid PRIMARY KEY DEFAULT gen_random_uuid(), denetim_no text NOT NULL UNIQUE, surec text NOT NULL, kapsam text NOT NULL, denetci_ref text NOT NULL REFERENCES kullanici_hesabi (kimlik), vekaleten boolean NOT NULL DEFAULT false, durum text NOT NULL DEFAULT 'Açık' CHECK (durum IN ('Açık', 'Raporda', 'Sonuçlandı')), rapor_ozeti text, olusturma_zamani timestamptz NOT NULL DEFAULT now(), kapanis_zamani timestamptz);
CREATE TABLE ic_denetim_bulgu (kimlik uuid PRIMARY KEY DEFAULT gen_random_uuid(), denetim_ref uuid NOT NULL REFERENCES ic_denetim (kimlik), sinif text NOT NULL CHECK (sinif IN ('Gözlem', 'Minör', 'Majör', 'Kritik')), tanim text NOT NULL, zaman timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE ON erisim_inceleme, erisim_inceleme_kalemi, etik_bildirim, ic_denetim TO yatonet_uygulama;
GRANT SELECT, INSERT ON ic_denetim_bulgu TO yatonet_uygulama;
